import{_ as t,c as a,o as r,b0 as s}from"./chunks/framework.Dmsv_Tiv.js";const o="/media-docs/assets/64b71fb1af2317aca8b83f9d0f748977.CN8yN_P-.gif",n="/media-docs/assets/6ca667742ce3ea7eb4b7b3f55f89f475.HV5S5VYD.gif",l="/media-docs/assets/0bdeb12f80b43a1d3a42eec75d826e67.DmYgVNjJ.gif",i="/media-docs/assets/8c1fc55afa674c4d4ea2f1d00e83a0e3.DcXIZWgA.png",c="/media-docs/assets/d542406d7dcb4e70bce253cee1785d29.BJ1sGqiQ.png",d="/media-docs/assets/1251718-20220918082633949-1246155665.Dn7sls4o.jpg",p="/media-docs/assets/1251718-20220918082653769-368164800.XQqlMOWB.jpg",C="/media-docs/assets/v2-a9ebf181ef35cfad1148a2f3dcc02dcc_r.D_lVfmdc.jpg",m="/media-docs/assets/v2-7bd857552bc442b35901a471f5fc4590_1440w.CxugSFyD.jpg",g="/media-docs/assets/v2-20787e28d1a3aba7c28d15da9cd08cca_1440w.Cpcgzx04.jpg",h="/media-docs/assets/1251718-20220918083042118-295476070.B0wCfxuW.png",_="/media-docs/assets/1251718-20220918083116967-1766864422.CukANjPx.png",b="/media-docs/assets/1251718-20220918083154436-152672541.BFB3zk0h.jpg",f="/media-docs/assets/v2-b53f6eec99877f2196c5df3d82a7f03a_1440w.sQuf-G0C.jpg",u="/media-docs/assets/9c536ca99d4275f59805c2a3d4ece253.Bg-XD8B9.png",D="/media-docs/assets/1251718-20220918082731783-1205066613.C_ebutx3.png",S="/media-docs/assets/ccd-a.mUedMmKC.jpg",O="/media-docs/assets/ccd-b.CoMruPHn.jpg",M="/media-docs/assets/ccd-c.CqLxgAD6.jpg",q="/media-docs/assets/1251718-20220918082911795-911778245.CHkDqkBk.png",k="/media-docs/assets/f60423f4e70115ed149249df170cbfaa.-knhKa_o.jpeg",y="/media-docs/assets/0edf2d4d5396fffe9374844a97f5687d.BP0RfFBz.jpeg",w="/media-docs/assets/1251718-20220918083031257-216194006.DRsq_jA4.png",P="/media-docs/assets/v2-317f2477eb2f66de5b8cd94cd4ca6be8_1440w.Dw-GgIKd.jpg",x="/media-docs/assets/1251718-20220918083128607-2104547728.C7YmhhUs.png",F="/media-docs/assets/1251718-20220918083207733-1808887386.Cm3u3A4l.jpg",T="/media-docs/assets/794d2625f23dd1d644cfec5d517a0a7b.Bbafw2Rc.gif",j="/media-docs/assets/1251718-20220918082952837-546321891.DX0c126n.jpg",z="/media-docs/assets/1251718-20220918083235055-1467242707.BxRumW3Y.png",B="/media-docs/assets/1251718-20220918083247087-390549267.C1Eq_AXH.png",N="/media-docs/assets/image-20251105195953959.BhiCReYp.png",R="/media-docs/assets/image-20251105200013252.DwAW1ORy.png",A="/media-docs/assets/ccd-out.SzAdNfAR.jpg",V="/media-docs/assets/cmos-out.DCYGckfn.jpg",H=JSON.parse('{"title":"LV035-CCD与CMOS","description":null,"frontmatter":{"title":"LV035-CCD与CMOS","date":"2025-11-07T16:13:57.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/camera/cam-basic/126b140c750d24fba85ee07f","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-07T16:13:57.591Z","fulluuid":"ba85ee07f1f04a80833a9a24ffe60501","useduuid":"ba85ee07f"}},"headers":[],"relativePath":"sdoc/camera/cam-basic/126b140c750d24fba85ee07f.md","filePath":"sdoc/05-Camera/01-Camera基础/LV035-CCD与CMOS.md","lastUpdated":1767537778000}'),v={name:"sdoc/camera/cam-basic/126b140c750d24fba85ee07f.md"};function I(G,e,E,L,Y,W){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="lv035-ccd与cmos" tabindex="-1">LV035-CCD与CMOS <a class="header-anchor" href="#lv035-ccd与cmos" aria-label="Permalink to &quot;LV035-CCD与CMOS&quot;">​</a></h1><h2 id="一、图像传感器分类" tabindex="-1">一、图像传感器分类 <a class="header-anchor" href="#一、图像传感器分类" aria-label="Permalink to &quot;一、图像传感器分类&quot;">​</a></h2><p>前面我们知道图像传感器是将光信号转换为电信号的设备，广泛应用于数码相机、摄像机、智能手机、无人机、自动驾驶汽车以及各种工业和医疗应用中。常见的图像传感器主要有以下几种：</p><ul><li>CCD 图像传感器</li></ul><p>CCD 的结构就象一排排输送带上并排放满了小桶，光线就像雨滴撒入各个小桶，每个小桶就是一个像素。按下快门拍照的过程，就是按一定的顺序测量在一个短暂的时间间隔中，小桶中落进了多少“光滴”，然后逐个记录下来并放大为电信号。这个记录的过程式串行工作的，所以早期的 CCD 数码相机虽然成像质量好，但是集成度受限制，连拍速度没有 CMOS 传感器的数码相机快。</p><img src="'+o+'" alt="img" style="zoom:67%;"><ul><li>CMOS 图像传感器</li></ul><p>CMOS 图像传感器的各个光电二极管都配备有放大器，因此可即时放大电流并一次性转换传输出去。所以具有速度快，功耗低的特点，早期的 CMOS 图像传感器存在噪点多、感光度低, 画质相对差的问题，但伴随技术发展，现在的 CMOS 传感器可以拍出超越 CCD 图像传感器的高画质视频与静止图像，在智能手机、数码相机等众多领域，CMOS 图像传感器成为了主流。</p><img src="'+n+'" alt="img" style="zoom:67%;"><ul><li>3D ToF 图像传感器</li></ul><p>3D ToF（Time of Flight，飞行时间） 图像传感器是一种基于测量光从传感器发射至目标物体到其返回的时间，从而构建三维图像数据的传感器。这种传感器通过计算光脉冲的飞行时间来确定物体与传感器之间的距离，从而生成三维点云数据。</p><img src="'+l+'" alt="img" style="zoom:67%;"><p>由于光速达到每秒约 30 万公里，如果直接测量光的反射时间，在进行细微的距离和图像检测的时候很难分辨出其飞行时间的差别。 所以一般来说 ToF 传感器会采用间接测量的方法，测量反射光相对于发射光的相位差来获取深度信息。传感器会发射调制过的红外光，并测量从不同距离的不同表面接收到的光的相位差。图中使用了两个接收检测器，第一个检测器的开关相位与发射光相同。会捕获一部分的反射光。而第二个检测接收器的开关相位与发射光相反，反射光也有另外一部分被其捕获，比较两个检测器捕获到的光子量的不同，就可以得到反射光相对于发射光的相位差，从而获得准确的距离信息。</p><img src="'+i+'" alt="read-normal-img" style="zoom:50%;"><p>ToF 传感器可以与 RGB 图像结合， 用算法组合 RGB 和深度图像，从而获得包含颜色和深度的场景和观察对象的 3D 信息，这在一些智能应用场景中具有重要作用，例如对汽车内乘客手势的识别。下图中的深度信息以颜色来表示，颜色越靠近红色，表明距离摄像头越近，越靠近蓝色，表明距离越远。</p><img src="'+c+'" alt="read-normal-img" style="zoom:50%;"><p>在汽车领域，TOF 被用于自动驾驶，防撞自动刹车、手势识别等功能。此外，TOF 也应用于手机的人脸识别，相机对焦，体感游戏中的 AR 与 VR 功能。</p><blockquote><p>这里有一篇 TI 的文档：<a href="https://www.ti.com.cn/cn/lit/an/zhca655/zhca655.pdf?ts=1733227715189" target="_blank" rel="noreferrer">3D ToF 三维场景距离（景深）测量系统简介</a>，主要介绍了 3D ToF 传感器的基本原理，里面提到的芯片是 OPT9221。</p></blockquote><h2 id="二、ccd-电荷耦合器件" tabindex="-1">二、CCD（电荷耦合器件） <a class="header-anchor" href="#二、ccd-电荷耦合器件" aria-label="Permalink to &quot;二、CCD（电荷耦合器件）&quot;">​</a></h2><h3 id="_1-ccd-简介" tabindex="-1">1. CCD 简介 <a class="header-anchor" href="#_1-ccd-简介" aria-label="Permalink to &quot;1. CCD 简介&quot;">​</a></h3><h4 id="_1-1-ccd-是什么" tabindex="-1">1.1 CCD 是什么？ <a class="header-anchor" href="#_1-1-ccd-是什么" aria-label="Permalink to &quot;1.1 CCD 是什么？&quot;">​</a></h4><p>CCD，Charge-Coupled Device，即电荷耦合器件。CCD 的基本感光单元，是金属氧化物半导体电容器（MOS = Metal Oxide Semiconductor Capacity），它用作光电二极管和存储设备。</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+d+'" style="width:50%;height:auto;"></td><td align="center" style="border:none;"><img src="'+p+'" style="width:50%;height:auto;"></td></tr></tbody></table> 典型的 CCD 器件有四层:（a）底部掺杂硼的硅衬底（Silicon Substrate）、（b）沟道停止层（Channel Stop）、（c）氧化层（Silicon Dioxide）和（d）用于控制的栅电极（Polysilicon Gate Electrode）。 <h4 id="_1-2-三种-ccd-架构" tabindex="-1">1.2 三种 CCD 架构 <a class="header-anchor" href="#_1-2-三种-ccd-架构" aria-label="Permalink to &quot;1.2 三种 CCD 架构&quot;">​</a></h4><p>CCD（电荷耦合器件）图像传感器体系可分为全帧（FF）、帧传输（FT）和行间传输（IT）三种 CCD 架构。</p><h5 id="_1-2-1-full-frame-ccd" tabindex="-1">1.2.1 Full frame CCD <a class="header-anchor" href="#_1-2-1-full-frame-ccd" aria-label="Permalink to &quot;1.2.1 Full frame CCD&quot;">​</a></h5><p>Full frame CCD 又叫全帧 CCD, 阵列的每一个像素都感光。传输时，每一列向单行串行寄存器上相应的位置转移。同时串行寄存器向 CCD 阵列的出口转移。Full frame 是可以利用整个感光区域，有效的增加了感光面积，同时也适应了长时间曝光。因此在上一帧曝光后，要先进行电荷输出，否则的话，下一帧曝光开始，上一帧还在读出阶段，就容易出现拖尾现象。因此这种 CCD 必须使用机械快门。同时也限制了 Full frame CCD 连续拍照的能力。</p><img src="'+C+'" alt="img" style="zoom:25%;"><p>为什么必须要机械快门?这是因为 CCD 的光激活区并不会因为已经决定是时候执行读出而停止光激活。如果没有在曝光周期完成后阻挡入射光的机械快门，或者说在读出过程中快门没有关闭，光线会持续照射到 CCD 上。那么，在电荷逐行向下转移的整个漫长过程中：</p><ul><li><strong>正在被读出的电荷</strong>：在向下移动的路径中，会继续受到光照，产生新的电荷，并与原始信号混合在一起。</li><li><strong>已经读出区域的像素</strong>：会开始新一轮的曝光，产生无关的电荷。</li><li><strong>尚未被读出的像素</strong>：在等待被读出的时间里，也会积累额外的、非预期的电荷。</li></ul><h5 id="_1-2-2-帧传输-frame-transfer-ccd" tabindex="-1">1.2.2 帧传输（Frame-Transfer）CCD <a class="header-anchor" href="#_1-2-2-帧传输-frame-transfer-ccd" aria-label="Permalink to &quot;1.2.2 帧传输（Frame-Transfer）CCD&quot;">​</a></h5><p>FT-CCD 允许我们保持 FF-CCD 的一些优点，同时（几乎）不需要快门。这是通过将 FF CCD 分成两个大小相等的部分来实现的。其中一个部分是普通的光敏成像阵列，另一个部分是屏蔽入射光的存储阵列。</p><img src="'+m+'" alt="img" style="zoom:33%;"><p>在集成之后，用于所有像素的电荷包被快速地传输到存储阵列，然后在存储阵列中发生读出。当读取存储位置时，活动像素可以为下一图像累积电荷，这使得帧传输 CCD 能够获得比全帧 CCD 更高的帧速率。</p><p>FT 架构的主要缺点是成本较高，并且相对于图像质量而言面积增大，因为基本上是使用 FF 传感器，然后将像素数减少两倍。</p><blockquote><p>帧传输 CCD 在全帧架构中增加了一个存储阵列</p></blockquote><h5 id="_1-2-3-线间传输-interline-transfer-ccd" tabindex="-1">1.2.3 线间传输（Interline-Transfer）CCD <a class="header-anchor" href="#_1-2-3-线间传输-interline-transfer-ccd" aria-label="Permalink to &quot;1.2.3 线间传输（Interline-Transfer）CCD&quot;">​</a></h5><p>Interline Transfer CCD 又叫线间传输 CCD，这种 CCD 曝光后所产生的电荷都被转移到附件的移位寄存器，通过垂直传送向下转移到底部，按一定排序输出。这种 CCD 的优点是在曝光后即可将电荷储存在寄存器，继续曝光速度较快，感光和传送不在同一列，从而避免了拖尾现象。缺点是寄存器占用了感光面面积，也相应的牺牲了动态范围，芯片的每个像素并不是都感光，对于定位测量要求比较高的应用会有影响。</p><img src="'+g+'" alt="img" style="zoom:33%;"><h3 id="_2-基本结构" tabindex="-1">2. 基本结构 <a class="header-anchor" href="#_2-基本结构" aria-label="Permalink to &quot;2. 基本结构&quot;">​</a></h3><p>CCD 传感器的基本单元是光电二极管或 MOS 电容构成的感光像素井。曝光期间，像素井内累积的电荷表示入射光子数量。在读出过程中，CCD 依赖严格的时序控制，将积累的电荷逐行、逐列“接力式”地向传感器边缘的输出放大器转移，最终将整块感光阵列中所有像素的电荷移出，并在相同放大器中读出信号。一个全帧率 CCD 架构图如下图所示：</p><p><img src="'+h+'" alt="img"></p><p>CCD 传感器电路框图大概如下所示：</p><p><img src="'+_+'" alt="img"></p><p>对于左侧信号的采集这部分，忽略电路板部分，只关注感光部分，大概类似于这样：</p><img src="'+b+'" alt="img" style="zoom:50%;"><p>总的来说，CCD 本质上是一个大阵列的半导体“桶”，可以将传入的光子转换为电子并保持累积的电荷。这些电荷通过逐行移位传输，即可以被垂直移位寄存器，向下转移到水平移位寄存器，水平移位寄存器以将电荷转换为电压并通过放大器输出。</p><h3 id="_3-特点" tabindex="-1">3. 特点 <a class="header-anchor" href="#_3-特点" aria-label="Permalink to &quot;3. 特点&quot;">​</a></h3><p>CCD 相机是全局曝光，全局曝光是传感器上所有像素在同一时刻开启曝光并在同一时刻曝光结束，将物体某时刻的状态成像，对运动物体而言，类似于将物体冻结了，所以适合拍摄高速运动的物体。但是它采用逐个光敏输出，速度较慢。</p><h4 id="_3-1-smear现象" tabindex="-1">3.1 Smear现象 <a class="header-anchor" href="#_3-1-smear现象" aria-label="Permalink to &quot;3.1 Smear现象&quot;">​</a></h4><p>CCD 会有 <strong>Smear</strong> 现象，smear 是 CCD 传感器在拍摄强烈点光源照射下的景物时出现光散射，形成条状光线影像的现象，一般称为漏光。这种称作漏光（Smear）的光散射现象是由于 CCD 传感器物理结构上的缺陷导致，从 CCD 的读取方向，即画面的垂直方向上入射的强光会穿透图像保护层产生多余影像而形成的，特别是没有使用机械快门的摄像机在拍摄时会有严重漏光现象。一般是 <strong>场景中存在极强光源或高反光物体</strong>，例如直接拍摄太阳、路灯等情况下会容易出现这种现象。</p><p><img src="'+f+'" alt="img"></p><h4 id="_3-2-blooming效应" tabindex="-1">3.2 Blooming效应 <a class="header-anchor" href="#_3-2-blooming效应" aria-label="Permalink to &quot;3.2 Blooming效应&quot;">​</a></h4><p>当场景中存在亮度较高的点光源或亮区域时，CCD在亮点光源附近区域会存在Blooming效应，也叫做“开花”、“光晕”、“光溢出”。</p><p>这个问题发生的原因是CCD传感器的像素在受到强光照射时，亮点区域像素光照太强，光电二极管在强光下产生的光电子数超过了CCD电荷存储区可存储的最大电子数而溢出，溢出的电子将沿行或列的方向进入到了相邻像素，“污染”了相邻图像区域 (专业说法是：使相邻区域也饱和了)。如下图照片中太阳周围一片像素的值基本都饱和了。</p><p><img src="'+u+'" alt="img"></p><h3 id="_5-电荷转移与读出机制" tabindex="-1">5. 电荷转移与读出机制 <a class="header-anchor" href="#_5-电荷转移与读出机制" aria-label="Permalink to &quot;5. 电荷转移与读出机制&quot;">​</a></h3><p>使用 CCD 相机生成图像，可分为四个主要阶段或功能：通过光子与器件光敏区域相互作用产生电荷、收集和存储释放的电荷、电荷转移和电荷测量。</p><p><img src="'+D+'" alt="img"></p><p>① 信号电荷的产生：第一步是电荷的产生。CCD 可以将入射光信号转换为电荷输出，依据的是半导体的内光电效应（光伏效应）。</p><p>② 信号电荷的存储：第二步是信号电荷的收集，就是将入射光子激励出的电荷收集起来成为信号电荷包的过程。</p><p>③ 信号电荷的传输（耦合）：第三步是信号电荷包的转移，就是将所收集起来的电荷包从 <strong>一个像元转移到下一个像元</strong>，直到全部电荷包输出完成的过程。</p><p>④ 信号电荷的检测：第四步是电荷的检测，就是将转移到输出级的电荷转化为电流或者电压的过程。</p><p>举个例子：</p><p>假设一个 N×M 的像素阵列，曝光结束后，每个像素内含有一定电荷(每个像素本身仅负责收集和存储电荷，不进行像素级放大或独立输出)。CCD 的控制时序使第一行电荷沿行方向转移到输出放大器的寄存器中，然后这一行电荷逐像素输出并转换为电压信号。接着第二行电荷移位到第一行位置，再输出，如此循环，直到所有像素的电荷被读出。</p><p>关于 CCD 工作原理，有一个经典的区域雨水测量比喻：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+S+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+O+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+M+'" style="width:100%;height:auto;"></td></tr></tbody></table><p>CCD 串行读出方式，可以用桶旅测量区域雨量来示意。其中落在桶阵列上的降雨强度可能因地而异，与成像传感器上的入射光子相似，如图（a）。这些桶在积分期间收集了不同数量的信号（水），桶在传送带上向代表串行寄存器（Serial Bucket Array）的一排空桶传送。在图（b），一整排存储桶被并行移动到串行寄存器的存储库中。串行移位和读出操作如图（c）所示，其中描绘了每个桶中累积的雨水被顺序转移到校准的测量容器中，这类似于 CCD 输出放大器。当串行传送带上所有容器的内容物按顺序测量完毕后，另一列并行班次（Parallel Register Shift）将下一行收集桶的内容物转移到串行记录容器中，重复该过程，直到每个桶（像素）的内容物都测量完毕。</p><p>这一过程就像流水线，把全片存储的电荷逐行、逐像素地移向输出放大器。由于此过程电荷严格按照线性顺序移动，像素与像素间匹配性很高，输出信号一致性好，从而降低固定模式噪声。</p><h3 id="_5-优势和不足" tabindex="-1">5. 优势和不足 <a class="header-anchor" href="#_5-优势和不足" aria-label="Permalink to &quot;5. 优势和不足&quot;">​</a></h3><ul><li><strong>优势</strong>：像素间一致性高，输出信号品质均匀，低固定模式噪声，图像质量优异；在早期成像器件中广泛应用于科研、天文成像和专业摄影器材。</li><li><strong>不足</strong>：CCD 逐行移位需要额外的电荷耦合路径，读出速度较慢，且功耗高。此外，制造 CCD 工艺复杂且成本较高，传感器面积大时的读出速度和复杂性也更具挑战。</li></ul><h2 id="三、cmos-互补金属氧化物半导体" tabindex="-1">三、CMOS（互补金属氧化物半导体） <a class="header-anchor" href="#三、cmos-互补金属氧化物半导体" aria-label="Permalink to &quot;三、CMOS（互补金属氧化物半导体）&quot;">​</a></h2><h3 id="_1-cmos-简介" tabindex="-1">1. CMOS 简介 <a class="header-anchor" href="#_1-cmos-简介" aria-label="Permalink to &quot;1. CMOS 简介&quot;">​</a></h3><p><strong>CMOS</strong> 称为互补式金属氧化物半导体（Complementary Metal-Oxide-Semiconductor，缩写作 CMOS），是一种集成电路的设计工艺，可以在硅质晶圆模板上制出 NMOS（n-type MOSFET）和 PMOS（p-type MOSFET）的基本元件，由于 NMOS 与 PMOS 在物理特性上为互补性，因此被称为 CMOS。它的微观结构图如下：</p><p><img src="'+q+'" alt="img"></p><blockquote><p>当前主流的 CMOS 厂商有：索尼、三星、豪威、格科微、思特威、安森美等公司。</p></blockquote><p>CMOS 还分为背照式、前照式、堆栈式：</p><p>前照式与背照式 CMOS 的区别很好理解，一种是电路层位于感光二极管前面，一种是电路层位于感光二极管后面。如上图所示，前照式 CMOS 的金属电路挡在受光面前面，这样会损失很多光线，真正能够被感光二极管接收和利用的光线只剩 70%甚至更少。很显然，背照式 CMOS 极大提高了光线利用率，可以提高传感器灵敏度，最明显的改善就是低照度环境下成像质量更高。</p><p><img src="'+k+'" alt="img"></p><p>这么“简单”的改进，就能明显提高画质，为什么不早这么做呢？</p><p>虽然只是结构上的小改动，但这意味着承载光电二极管的基板要非常薄，大概是传统 CMOS 的百分之一，对生产工艺和技术要求相当高。所以发展到足够的技术水平后，才出现背照式 CMOS。2008 年的 6 月，索尼公司正式发布了背照式 CMOS 传感器。直至今天，手机上采用的几乎都是背照式 CMOS。</p><p>堆栈式，也叫堆叠式、积层式。本来像素区域（负责感光）与处理电路（负责处理信号）都在同一晶圆上进行蚀刻，堆叠式是把二者分开了，像素区域在上，处理电路在下，二者堆叠起来“各司其职”，所以叫堆叠式。</p><img src="'+y+'" alt="img" style="zoom:50%;"><p>堆叠式的好处，最在于“各司其职”。像素部分和电路部分分别独立，像素部分可针对高画质优化，电路部分可针对高性能优化。比如，像素部分直接用 65nm 制程（可理解为制造精度）足够了，但电路部分用这样的制程就太粗糙了，二者分开以后，电路部分就可以采用更高精度的制程提高信号处理能力。</p><h3 id="_2-基本结构-1" tabindex="-1">2. 基本结构 <a class="header-anchor" href="#_2-基本结构-1" aria-label="Permalink to &quot;2. 基本结构&quot;">​</a></h3><p>CMOS 传感器的架构图如下：</p><p><img src="'+w+'" alt="img"></p><p>CMOS 像素是一个 <strong>集成了感光与放大功能的微电路单元，使得每个像素可以直接输出电压信号</strong>。换言之，CMOS 中每个像素不仅有光电二极管（感光元件），还内置若干有源元件（如 MOSFET 晶体管）以实现信号的放大与读出。这种结构为随机访问与高速读出奠定基础。</p><ul><li>光电二极管（Photodiode）：将光转化为电荷。</li><li>转换晶体管（Transfer Gate）：控制电荷从光电二极管转移至储存节点或直接到源跟随器。</li><li>源跟随放大器（Source Follower）：每个像素具有自己的小型放大电路，将电荷信号直接转换为电压信号。</li><li>复位晶体管（Reset）：将存储节点复位到参考电压。</li><li>行选择晶体管（Row Select）：选择性地将该像素输出到列总线上。</li></ul><p>下图是看到的一个像素结构的示意图：</p><p><img src="'+P+'" alt="img"></p><p>电路原理框图大概如下：</p><p><img src="'+x+'" alt="img"></p><p>忽略电路板部分，只关注感光部分，有如下的示意图：</p><img src="'+F+'" alt="img" style="zoom:67%;"><p>互补金属氧化物半导体设计不是传输电荷桶，而是立即将电荷转换为电压，并在微线上输出电压。</p><h3 id="_3-特点-1" tabindex="-1">3. 特点 <a class="header-anchor" href="#_3-特点-1" aria-label="Permalink to &quot;3. 特点&quot;">​</a></h3><p>CMOS 相机是卷帘曝光，卷帘曝光是逐行顺序开启曝光，不同行间曝光的开启时刻有个很小的延迟，高速运动物体可能会产生<strong>Rolling shutter问题</strong>（常说的果冻效应），但是现在也有 <strong>全域快门</strong>，整个 CMOS 同时曝光，比如索尼 A93，就是很贵。CMOS 有多个电荷-电压转换器和行列开关控制，读出速度快很多.</p><p>可以看一下果冻效应产生的原因：</p><p>使用逐行曝光的sensor所致，因为sensor是逐行曝光的，行与行之间有时间差，当拍摄快速运动的物体时，会导致成像物体会有扭曲，被拉长了，注意要和曝光时间导致的拖影做区分，曝光时间过长会有拖影，但不会导致成像物有变形；</p><p><img src="'+T+'" alt="img"></p><p>措施：</p><p>（1）通过提高帧率、减少一行时间可以减少曝光时间，能缓解果冻效应 。</p><p>（2）换全局快门（Global Shutter）的 sensor，能彻底解决果冻效应，全局快门的 sensor 可以允许所有的像素在同一时间开始和结束曝光，曝光结束后再顺序读出。因为所有像素曝光的时间都在同一时间点，不会有时间差，所以不会出现拍摄快速运动物体时的果冻效应。</p><blockquote><p>关于 CMOS 的快门，这里有一篇文档做了详细介绍：<a href="https://www.edn.com/digital-camera-design-part-3-cmos-rolling-shutter-and-global-reset-schemes/" target="_blank" rel="noreferrer">Digital camera design, part 3: CMOS rolling shutter and global reset schemes - EDN</a></p></blockquote><h3 id="_4-随机访问与并行读出" tabindex="-1">4. 随机访问与并行读出 <a class="header-anchor" href="#_4-随机访问与并行读出" aria-label="Permalink to &quot;4. 随机访问与并行读出&quot;">​</a></h3><p>CMOS 的像元工作示意图如下：</p><img src="'+j+'" alt="img" style="zoom:55%;"><p>与 CCD 需要逐行移位电荷不同，CMOS 通过地址逻辑可随意访问任何一行像素。当行选择晶体管被激活，该行像素的信号通过列线输出到读出电路。</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+z+'" style="width:100%;height:auto;"></td><td align="center" style="border:none;"><img src="'+B+'" style="width:100%;height:auto;"></td></tr></tbody></table><p>这种架构允许 CMOS 传感器同时对多行进行操作，从而实现高速读出。CMOS 的读出过程更像在处理一个二维阵列的内存寻址，可以提高帧速率，减少功耗，还能实现局部放大（Region of Interest）读取。</p><h3 id="_5-cmos-的放大与噪声特性" tabindex="-1">5. CMOS 的放大与噪声特性 <a class="header-anchor" href="#_5-cmos-的放大与噪声特性" aria-label="Permalink to &quot;5. CMOS 的放大与噪声特性&quot;">​</a></h3><p>虽然每个像素都有独立放大器，但这会导致像素间存在固定模式噪声（FPN）：由于工艺微差，每个像素的放大器增益或偏置电平略有不同，从而在图像上呈现固定的条纹或斑点状噪声。</p><p>为减小 FPN，CMOS 传感器通常配备片上校正电路和后期数字校正，通过双采样（Correlated Double Sampling, CDS）和数字电路减少读出过程中的偏移与噪声。</p><h3 id="_6-优势和不足" tabindex="-1">6. 优势和不足 <a class="header-anchor" href="#_6-优势和不足" aria-label="Permalink to &quot;6. 优势和不足&quot;">​</a></h3><ul><li><strong>优势</strong>：低功耗、高速读出、制造成本相对较低（可与标准 CMOS 工艺兼容），易于集成片上处理电路（ISP）。因此 CMOS 传感器逐渐在消费级数码相机、手机摄影、车载摄像头和各类嵌入式成像领域占据主流。</li><li><strong>不足</strong>：早期 CMOS 器件噪声较高、画质不如 CCD，但随着工艺进步和信号处理技术的提升，CMOS 画质已大幅改善。在高端应用中（科学成像、医疗或天文）CMOS 方案也正快速普及。</li></ul><h2 id="四、ccd-与-cmos-对比" tabindex="-1">四、CCD 与 CMOS 对比 <a class="header-anchor" href="#四、ccd-与-cmos-对比" aria-label="Permalink to &quot;四、CCD 与 CMOS 对比&quot;">​</a></h2><p>CCD 和 CMOS 传感器是目前最常见的感光传感器，广泛应用于数码相机、数码摄像机、照相手机和摄像头等产品上。两者在结构、性能和技术上均不尽相同。</p><table><tbody><tr><td colspan="3" align="center"> CCD VS CMOS </td></tr><tr><td align="center" width="150px"> 对比项目 </td> <td align="center"> CCD 传感器 </td> <td align="center"> CMOS 传感器 </td></tr><tr><td align="center"> 全名 </td> <td align="center"> 电荷耦合器件传感器 </td> <td align="center"> 金属氧化物半导体传感器 </td></tr><tr><td align="center"> 像元水桶模型 </td> <td align="center"><img src="'+N+'"></td> <td align="center"><img src="'+R+'"></td></tr><tr><td align="center"> 传输逻辑 </td> <td align="center"> CCD 像元产生的电荷，需要先寄存在垂直寄存器中，然后分行传送到水平寄存器，最后单独依次测量每个像元的电荷并放大输出信号。<br><img src="'+A+'"></td> <td align="center"> 在每个像素上使用晶体管, 电荷通过传统导线移动, 每个像素都得到单独的处理。<br><img src="'+V+'"></td></tr><tr><td align="center"> 像元信号 </td> <td align="center"> 电荷 </td> <td align="center"> 电压 </td></tr><tr><td align="center"> 图像质量 </td> <td align="center"> CCD 技术起步早，采用 PN 结或二氧化硅隔离层隔离噪声，有一定优势，但随着技术发展，已无压倒性优势 </td> <td align="center"> 早期 CMOS 由于光电传感元件、电路间距离很近，光、电、磁干扰严重，成像质量差。随着 CMOS 电路消噪技术发展，和 CCD 已相差无几 </td></tr><tr><td align="center"> 图像分辨率 </td> <td align="center"> 高 </td> <td align="center"> 稍低 </td></tr><tr><td align="center"> 处理速度 </td> <td align="center"> 低，同步信号控制下串行逐行移位读取，速度较慢 </td> <td align="center"> 高，每个像素有单独电路，信号读取简单，速度较 CCD 快很多 </td></tr><tr><td align="center"> 噪点 </td> <td align="center"> 只有一个放大器放在芯片边缘，噪点较少 </td> <td align="center"> 每个像素都搭配一个放大器，放大器之间难以做到一致，噪点相对较多 </td></tr><tr><td align="center"> 对光的敏感度 </td> <td align="center"> 更高 </td> <td align="center"> 较低 </td></tr><tr><td align="center"> 功耗 </td> <td align="center"> 被动式采集图像，必须外加电压让每个像素中的电荷移动到传输通道，功耗高于 CMOS。 </td> <td align="center"> 主动式采集图像，像素中的电荷直接由旁边的晶体管放大输出，功耗较低。 </td></tr><tr><td align="center"> 发热 </td> <td align="center"> 更多 </td> <td align="center"> 较少 </td></tr><tr><td align="center"> 成本 </td> <td align="center"> 采用电荷传递方式，只要其中一个像素异常，会导致整排数据失效。良品率低，制造要求高，成本高于 CMOS。 </td> <td align="center"> 和一般半导体电路使用相同的 CMOS 工艺，可以轻易集成周边电路到芯片中，成本较低。 </td></tr><tr><td align="center"> 快门 </td> <td align="center"> 全局快门(几乎同时捕捉所有光线)</td> <td align="center"> 滚动快门(从上到下分行暴光)</td></tr><tr><td align="center"> 制造工艺 </td> <td align="center"> 复杂 </td> <td align="center"> 简单 </td></tr></tbody></table><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/m0_66890670/article/details/144409018" target="_blank" rel="noreferrer">相机（Camera）成像原理详解_相机成像原理-CSDN 博客</a></p><p><a href="https://blog.csdn.net/yxriyin/article/details/111449318" target="_blank" rel="noreferrer">PBR 来龙去脉篇一：光和人眼感知颜色_人眼亮度敏感曲线-CSDN 博客</a></p><p><a href="https://www.microdemo.com/technical-data/1267/" target="_blank" rel="noreferrer">图像传感器原理介绍\v（史上最详细的 CCD 和 CMOS 介绍）_微视界</a></p><p><a href="https://www.cnblogs.com/wujianming-110117/p/16704188.html" target="_blank" rel="noreferrer">全面详细解析 CMOS 和 CCD 图像传感器 - 吴建明 wujianming - 博客园</a></p><p><a href="https://blog.csdn.net/weixin_49586308/article/details/123315930" target="_blank" rel="noreferrer">CMOS 图像传感器的参数和评价标准_cmos 弱光-CSDN 博客</a></p><p><a href="https://www.cnblogs.com/ljbguanli/p/19107678" target="_blank" rel="noreferrer">工业相机与镜头靶面尺寸的关系：从原理到选型的避坑指南 - 教程 - ljbguanli - 博客园</a></p><p><a href="https://zhuanlan.zhihu.com/p/1930666322586501292" target="_blank" rel="noreferrer">(3 封私信) 工业相机的靶面是什么？它影响了哪些因素？ - 知乎</a></p><p><a href="https://zhuanlan.zhihu.com/p/139394687" target="_blank" rel="noreferrer">(3 封私信) 键盘摄影（五）——相机成像元件：CMOS/CCD - 知乎</a></p><p><a href="https://blog.csdn.net/vivo01/article/details/123529563" target="_blank" rel="noreferrer">Camera 和 Image sensor 技术基础笔记(1) -- 光和 CCD/CMOS sensor 基础知识_sensor blooming-CSDN 博客</a></p><p><a href="https://www.cnblogs.com/wujianming-110117/p/16704188.html" target="_blank" rel="noreferrer">全面详细解析 CMOS 和 CCD 图像传感器 - 吴建明 wujianming - 博客园</a></p><p><a href="https://cloud.tencent.com/developer/article/1934252" target="_blank" rel="noreferrer">堆栈式 CMOS、背照式 CMOS 和传统 CMOS 传感器的区别-腾讯云开发者社区-腾讯云</a></p><p><a href="https://www.zhihu.com/question/19948428" target="_blank" rel="noreferrer">(3 封私信) Full frame CCD 和 Interline CCD 有何区别，性能有何差异？ - 知乎</a></p><p><a href="https://zhuanlan.zhihu.com/p/613455759" target="_blank" rel="noreferrer">(3 封私信) 一文带你看懂三种 CCD 图像传感器 - 知乎</a></p><p><a href="https://blog.csdn.net/qq_35247586/article/details/124719614" target="_blank" rel="noreferrer">摄像头拍摄运动物体，产生运动模糊/拖影的原因分析_相机拖影是怎么造成的-CSDN博客</a></p></blockquote>',121)])])}const $=t(v,[["render",I]]);export{H as __pageData,$ as default};
